"""Conway's Game of Life, with every generation computed by a GPU compute kernel.

Usage: uv run main.py <input-file>

The input file holds "<width> <height> <generations>" followed by height rows
of width digits (0 or 1) separated by single spaces. The final grid is written
to standard output in the same row format, followed by "ALIVE <count>".
"""

import struct
import sys

import wgpu

WORKGROUP = 16

SHADER = """
struct Params {
    width: u32,
    height: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= params.width || y >= params.height) {
        return;
    }

    var neighbours: u32 = 0u;
    for (var dy: i32 = -1; dy <= 1; dy = dy + 1) {
        for (var dx: i32 = -1; dx <= 1; dx = dx + 1) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = i32(x) + dx;
            let ny = i32(y) + dy;
            if (nx >= 0 && ny >= 0 && u32(nx) < params.width && u32(ny) < params.height) {
                neighbours = neighbours + src[u32(ny) * params.width + u32(nx)];
            }
        }
    }

    let alive = src[y * params.width + x];
    var next: u32 = 0u;
    if (alive == 1u) {
        if (neighbours == 2u || neighbours == 3u) {
            next = 1u;
        }
    } else if (neighbours == 3u) {
        next = 1u;
    }
    dst[y * params.width + x] = next;
}
"""


def parse(text):
    """Return (width, height, generations, cells) read from the input text.

    Cells are a flat row-major list of 0/1 integers. Header numbers are taken
    as whitespace-separated tokens; the cell digits are every 0 or 1 character
    after the header, so spacing within the rows does not matter.
    """
    tokens = text.split()
    width, height, generations = (int(tokens[i]) for i in range(3))
    digits = "".join(tokens[3:])
    cells = [int(c) for c in digits if c in "01"][: width * height]
    return width, height, generations, cells


def run(width, height, generations, cells):
    """Advance the grid by the given number of generations on the GPU."""
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    size = width * height * 4
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    buffers = [
        device.create_buffer_with_data(data=struct.pack(f"{width * height}I", *cells), usage=usage),
        device.create_buffer(size=size, usage=usage),
    ]
    params = device.create_buffer_with_data(
        data=struct.pack("II", width, height),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": module, "entry_point": "step"},
    )
    layout = pipeline.get_bind_group_layout(0)

    # Generation g reads buffers[g % 2] and writes buffers[(g + 1) % 2], so the
    # next generation sees only what this one left behind.
    bind_groups = [
        device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": 8}},
                {"binding": 1, "resource": {"buffer": buffers[i], "offset": 0, "size": size}},
                {"binding": 2, "resource": {"buffer": buffers[1 - i], "offset": 0, "size": size}},
            ],
        )
        for i in range(2)
    ]

    groups_x = (width + WORKGROUP - 1) // WORKGROUP
    groups_y = (height + WORKGROUP - 1) // WORKGROUP

    encoder = device.create_command_encoder()
    for generation in range(generations):
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, bind_groups[generation % 2])
        compute.dispatch_workgroups(groups_x, groups_y)
        compute.end()

    final = buffers[generations % 2]
    readback = device.create_buffer(size=size, usage=wgpu.BufferUsage.COPY_DST | wgpu.BufferUsage.MAP_READ)
    encoder.copy_buffer_to_buffer(final, 0, readback, 0, size)
    device.queue.submit([encoder.finish()])

    readback.map_sync(wgpu.MapMode.READ)
    result = list(struct.unpack(f"{width * height}I", readback.read_mapped()))
    readback.unmap()
    return result


def format_grid(width, height, cells):
    lines = []
    for y in range(height):
        row = cells[y * width : (y + 1) * width]
        lines.append(" ".join(str(c) for c in row))
    lines.append(f"ALIVE {sum(cells)}")
    return "\n".join(lines) + "\n"


def main(argv):
    if len(argv) != 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2

    with open(argv[1], encoding="utf-8") as f:
        width, height, generations, cells = parse(f.read())

    if generations > 0:
        cells = run(width, height, generations, cells)

    sys.stdout.write(format_grid(width, height, cells))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

